INSERT IGNORE INTO `ContentItem` (`id`, `type`, `titleAr`, `titleEn`, `bodyAr`, `bodyEn`, `status`, `metadata`, `createdById`, `updatedById`, `createdAt`, `updatedAt`) VALUES ('cmtn1f5wt0004hcvc7myz5rjc', 'page_section', 'لست متأكداً من موقعك؟ ابدأ التقييم المجاني لأعمالك.', 'Not sure where you stand? Start your free business assessment.', 'تسعة أسئلة عن الحجم والالتزام والنضج المالي تُنتج درجة جاهزية ومؤشرات مخاطر وخطة استشارية موصى بها — في أقل من أربع دقائق.', 'Nine questions on size, compliance and financial maturity produce a readiness score, risk indicators, and a recommended advisory plan — in under four minutes.', 'published', '{"page":"homepage","sectionKey":"assessment","fields":{}}', 'cadmini0o95r2vx5mux5f59q', 'cadmini0o95r2vx5mux5f59q', '2026-09-04 14:16:47.021', '2026-09-23 09:48:41.874');
