INSERT IGNORE INTO `ContentItem` (`id`, `type`, `titleAr`, `titleEn`, `bodyAr`, `bodyEn`, `status`, `metadata`, `createdById`, `updatedById`, `createdAt`, `updatedAt`) VALUES ('cmtztmlx80005m8vctzk6k4jx', 'page_section', 'أعمالك. متصلة.', 'Your Business. Connected.', 'نطلق قريباً تطبيقنا الرقمي الجديد — مساحة آمنة وسلسة تجمع مهامك ومستنداتك وتقاريرك ومواعيدك الضريبية في مكان واحد. كن أول من يعرف.', 'We’re launching our new digital app soon — a secure, seamless space that brings your engagements, documents, reports, and tax deadlines together in one place. Be the first to know.', 'published', '{"page":"v2","sectionKey":"digital","fields":{"badge":{"ar":"قريباً","en":"Coming Soon"},"eyebrow":{"ar":"التطبيق الجديد للعملاء","en":"The New Client App"},"notifyCta":{"ar":"أعلمني","en":"Notify Me"}}}', 'cadmini0o95r2vx5mux5f59q', 'cadmini0o95r2vx5mux5f59q', '2026-09-13 12:59:37.724', '2026-09-23 09:48:42.206');
