INSERT IGNORE INTO `ContentItem` (`id`, `type`, `titleAr`, `titleEn`, `bodyAr`, `bodyEn`, `status`, `metadata`, `createdById`, `updatedById`, `createdAt`, `updatedAt`) VALUES ('cmtztmlyl0007m8vcot8sfz9j', 'page_section', 'نحن هنا لمساعدتك في التخطيط لما هو قادم.', 'We are here to help you plan for what comes next.', 'تواصل معنا', 'Contact Us', 'published', '{"page":"v2","sectionKey":"contact","fields":{"callLabel":{"ar":"اتصل بنا","en":"Call us"},"phone":{"ar":"+۲۰ ۱۱۱ ۲۰٤ ۲۰۹۸","en":"+20 111 204 2098"},"emailLabel":{"ar":"البريد الإلكتروني","en":"Email"},"email":{"ar":"info@sherifadvisory.com","en":"info@sherifadvisory.com"},"hqLabel":{"ar":"المقر الرئيسي","en":"Headquarters"},"hqValue":{"ar":"القاهرة الجديدة، القاهرة، مصر","en":"New Cairo, Cairo, Egypt"},"formTitle":{"ar":"لنبدأ العمل","en":"Let\'s get you started"}}}', 'cadmini0o95r2vx5mux5f59q', 'cadmini0o95r2vx5mux5f59q', '2026-09-13 12:59:37.773', '2026-09-23 09:48:42.267');
