INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmtie3jv2000450vcst066z8g', 'cmt7crew500012wvctlfl2mur', 8, '{"type":"service","titleAr":"استشارة قانونية","titleEn":"Legal consultation","bodyAr":"الاستشارة القانونية تتيح لك التحدث معنا و الحصول علي الاستشارة الازمة ","bodyEn":"Legal consultation allows you to speak with us and receive the necessary advice.","status":"published","metadata":{"icon":"Users","displayOrder":1,"descriptionAr":"الاستشارة القانونية تتيح لك التحدث معنا و الحصول علي الاستشارة الازمة ","descriptionEn":"Legal consultation allows you to speak with us and receive the necessary advice.","fullDescriptionEn":"","fullDescriptionAr":"","image":"/uploads/1787606387882-29gw02q6.png","imageId":"cmt7qosph0000b4vcx80ondj7"}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-01 08:12:49.358');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmtie7fgr000650vc04dai0uq', 'cmt7crew500012wvctlfl2mur', 9, '{"type":"service","titleAr":"استشارة قانونية","titleEn":"Legal consultation","bodyAr":"الاستشارة القانونية تتيح لك التحدث معنا و الحصول علي الاستشارة الازمة ","bodyEn":"Legal consultation allows you to speak with us and receive the necessary advice.","status":"published","metadata":{"icon":"Users","displayOrder":1,"descriptionAr":"الاستشارة القانونية تتيح لك التحدث معنا و الحصول علي الاستشارة الازمة ","descriptionEn":"Legal consultation allows you to speak with us and receive the necessary advice.","fullDescriptionEn":"Our legal consultation service gives you direct access to experienced legal professionals who understand your unique circumstances and concerns. Whether you\'re facing a specific legal issue, need clarity on your rights and obligations, or are simply seeking guidance before making an important decision, our team is here to listen carefully and provide clear, practical advice tailored to your situation. We take the time to explain legal matters in plain language, helping you understand your options and the best path forward. Through this consultation, you\'ll receive the professional insight and necessary guidance to move ahead with confidence, whether that means resolving a dispute, understanding a contract, or planning your next steps with full awareness of the legal implications involved.","fullDescriptionAr":"توفر لك خدمة الاستشارة القانونية لدينا إمكانية التواصل المباشر مع نخبة من المختصين القانونيين ذوي الخبرة، الذين يتفهمون ظروفك واحتياجاتك الخاصة. سواء كنت تواجه مشكلة قانونية محددة، أو تحتاج إلى توضيح لحقوقك والتزاماتك، أو تسعى فقط للحصول على إرشاد قبل اتخاذ قرار مهم، فإن فريقنا هنا للاستماع إليك بعناية وتقديم النصح الواضح والعملي الذي يناسب وضعك. نحرص على شرح الأمور القانونية بلغة مبسطة وسهلة الفهم، لمساعدتك على إدراك خياراتك المتاحة وأفضل السبل للمضي قدمًا. ومن خلال هذه الاستشارة، ستحصل على الرؤية المهنية والإرشاد اللازم للتقدم بثقة، سواء كان ذلك لحل نزاع، أو فهم عقد، أو التخطيط لخطواتك القادمة مع إدراك تام للآثار القانونية المترتبة عليها.","image":"/uploads/1787606387882-29gw02q6.png","imageId":"cmt7qosph0000b4vcx80ondj7"}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-01 08:15:50.283');
