INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmtqbkd240009ikzhk2614c2z', 'cmt5qom2e00012cvcwchvpkmc', 11, '{"type":"page_section","titleAr":"شريف يسري لخدمات الاستشارات وإدارة الأعمال","titleEn":"Homepage Hero","bodyAr":"<pre><code class=\\"language-typescriptreact\\">استشارات متكاملة للشركات التي تخطّط لما هو قادم. نجمع بين انضباط المكاتب الكبرى والخبرة المحلية والتنفيذ الرقمي عبر منطقة الشرق الأوسط وشمال أفريقيا.</code></pre><p></p>","bodyEn":"<p>Welcome to Sherif Yousry Advisory for Finance &amp; Tax</p>","status":"published","metadata":{"page":"homepage","sectionKey":"hero","fields":{}}}', '["bodyAr"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-06 21:24:04.252');
