INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmtqdhqqd000qikzh92uay8kq', 'cmtmxh5oq00007kvcdqqj4u0t', 4, '{"type":"service","titleAr":"محاسبة ضريبية","titleEn":"TAX ADVISORY","bodyAr":"ىاعتلالي لالقثلعه32عثللاثصهلا","bodyEn":"Turning tax complexity into clarity and strategic value.\\n\\nTax compliance, tax planning, international taxation, transfer pricing, tax inspections, disputes, objections, refunds and transaction tax advisory.","status":"published","metadata":{"icon":"Calculator","displayOrder":2,"descriptionAr":"ىاعتلالي لالقثلعه32عثللاثصهلا","descriptionEn":"Turning tax complexity into clarity and strategic value.\\n\\nTax compliance, tax planning, international taxation, transfer pricing, tax inspections, disputes, objections, refunds and transaction tax advisory.","fullDescriptionEn":"Turning tax complexity into clarity and strategic value.\\n\\nTax compliance, tax planning, international taxation, transfer pricing, tax inspections, disputes, objections, refunds and transaction tax advisory.","fullDescriptionAr":"ىاعتلالي لالقثلعه32عثللاثصهلا","image":"/uploads/1788525161878-y6wtv0hy.jpeg","imageId":"cmtmxpb4v00027kvcqyav6yee"}}', '["bodyAr","metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-06 22:18:01.237');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmtqdkcwr000rikzhv45vh08d', 'cmt7crew500012wvctlfl2mur', 11, '{"type":"service","titleAr":"استشارة قانونية","titleEn":"AUDIT, ACCOUNTING & ASSURANCE","bodyAr":"الاستشارة القانونية تتيح لك التحدث معنا و الحصول علي الاستشارة الازمة ","bodyEn":"Reliable financial information. Greater confidence in every decision.\\n\\nAudit, assurance, accounting, financial reporting and independent review services designed to strengthen transparency, accuracy and stakeholder confidence.\\n","status":"published","metadata":{"icon":"Users","displayOrder":1,"descriptionAr":"الاستشارة القانونية تتيح لك التحدث معنا و الحصول علي الاستشارة الازمة ","descriptionEn":"Reliable financial information. Greater confidence in every decision.\\n\\nAudit, assurance, accounting, financial reporting and independent review services designed to strengthen transparency, accuracy and stakeholder confidence.\\n","fullDescriptionEn":"Reliable financial information. Greater confidence in every decision.\\n\\nAudit, assurance, accounting, financial reporting and independent review services designed to strengthen transparency, accuracy and stakeholder confidence.","fullDescriptionAr":"توفر لك خدمة الاستشارة القانونية لدينا إمكانية التواصل المباشر مع نخبة من المختصين القانونيين ذوي الخبرة، الذين يتفهمون ظروفك واحتياجاتك الخاصة. سواء كنت تواجه مشكلة قانونية محددة، أو تحتاج إلى توضيح لحقوقك والتزاماتك، أو تسعى فقط للحصول على إرشاد قبل اتخاذ قرار مهم، فإن فريقنا هنا للاستماع إليك بعناية وتقديم النصح الواضح والعملي الذي يناسب وضعك. نحرص على شرح الأمور القانونية بلغة مبسطة وسهلة الفهم، لمساعدتك على إدراك خياراتك المتاحة وأفضل السبل للمضي قدمًا. ومن خلال هذه الاستشارة، ستحصل على الرؤية المهنية والإرشاد اللازم للتقدم بثقة، سواء كان ذلك لحل نزاع، أو فهم عقد، أو التخطيط لخطواتك القادمة مع إدراك تام للآثار القانونية المترتبة عليها.","image":"/uploads/1788250530647-wnvq6u5q.jpeg","imageId":"cmtie70bp000550vcofyfwio1"}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-06 22:20:03.291');
