INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmudve2t80002zovc3lfjom8o', 'cmtmxh5oq00007kvcdqqj4u0t', 8, '{"type":"service","titleAr":"محاسبة ضريبية","titleEn":"TAX ADVISORY","bodyAr":"معلومات مالية موثوقة. وثقة أكبر في كل قرار. خدمات التدقيق، وخدمات التأكيد، والمحاسبة، وإعداد التقارير المالية، والمراجعة المستقلة، والمصممة لتعزيز الشفافية والدقة وثقة أصحاب المصلحة.","bodyEn":"Turning tax complexity into clarity and strategic value.\\n\\nTax compliance, tax planning, international taxation, transfer pricing, tax inspections, disputes, objections, refunds and transaction tax advisory.","status":"published","metadata":{"icon":"Calculator","displayOrder":2,"descriptionAr":"معلومات مالية موثوقة. وثقة أكبر في كل قرار. خدمات التدقيق، وخدمات التأكيد، والمحاسبة، وإعداد التقارير المالية، والمراجعة المستقلة، والمصممة لتعزيز الشفافية والدقة وثقة أصحاب المصلحة.","descriptionEn":"Turning tax complexity into clarity and strategic value.\\n\\nTax compliance, tax planning, international taxation, transfer pricing, tax inspections, disputes, objections, refunds and transaction tax advisory.","fullDescriptionEn":"Turning tax complexity into clarity and strategic value.\\n\\nTax compliance, tax planning, international taxation, transfer pricing, tax inspections, disputes, objections, refunds and transaction tax advisory.","fullDescriptionAr":"معلومات مالية موثوقة. وثقة أكبر في كل قرار. خدمات التدقيق، وخدمات التأكيد، والمحاسبة، وإعداد التقارير المالية، والمراجعة المستقلة، والمصممة لتعزيز الشفافية والدقة وثقة أصحاب المصلحة.","image":"","imageId":""}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 08:57:45.404');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmudx5dte000zi8vc605nlwnw', 'cmt5qom7200032cvc3lyi5lil', 3, '{"type":"page_section","titleAr":"من نحن","titleEn":"About Page","bodyAr":"نبذة عن شريف يسري للاستشارات","bodyEn":"About Sherif Yousry Advisory","status":"published","metadata":{"page":"about","sectionKey":"main","fields":{}}}', '["titleEn"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 09:46:58.994');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmudxe6cw001li8vc5lb0brme', 'cmudx7l9z0001ngvcen8ay3rl', 1, '{"type":"page_section","titleAr":"بدأنا بحلم تحويل الاستشارات إلى أثر حقيقي.","titleEn":"We started with a vision to turn advisory into real-world impact.","bodyAr":"تأسست شريف يسري للاستشارات بهدف تقديم خدمات استشارية متخصصة تجمع بين الخبرة الفنية العميقة والفهم الحقيقي لاحتياجات الأعمال.\\n\\nعلى مدار السنوات الماضية، أصبحنا شريكاً موثوقاً للشركات المتوسطة والكبيرة في مصر ومنطقة الشرق الأوسط وشمال أفريقيا، نساعدهم على التعامل مع التحديات الضريبية والقانونية والمالية بثقة وكفاءة.\\n\\nما يميّزنا هو التزامنا بالجودة والنزاهة، ورؤيتنا الشاملة التي تجمع بين الخبرة المحلية والمنظور الدولي.","bodyEn":"Sherif Yousry Advisory was founded with a clear purpose: to deliver specialised advisory services that combine deep technical expertise with a genuine understanding of business needs.\\n\\nOver the years we have become a trusted partner for medium and large enterprises across Egypt and the MENA region, helping them navigate tax, legal, and financial challenges with confidence and precision.\\n\\nWhat sets us apart is our commitment to quality and integrity, and our holistic view combining local expertise with an international perspective.","status":"published","metadata":{"page":"about","sectionKey":"story","fields":{"eyebrow":{"ar":"قصتنا","en":"OUR STORY"}}}}', '["bodyEn"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 09:53:49.232');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmudzuw24001wi8vcz7sae4sc', 'cmt5qom7200032cvc3lyi5lil', 4, '{"type":"page_section","titleAr":"من نحن","titleEn":"About Page","bodyAr":"نبذة عن شريف يسري للاستشارات","bodyEn":"About Sherif Yousry Advisory","status":"published","metadata":{"page":"about","sectionKey":"main","fields":{}}}', '["titleEn"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 11:02:48.268');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue12f72002ci8vc0bd951bi', 'cmudx7lks0008ngvc0bdyl74f', 1, '{"type":"event","titleAr":"قمة شريف يسري للاستشارات للأعمال السنوية","titleEn":"Annual Sherif Yousry Advisory Business Summit","bodyAr":"انضم إلى قادة الصناعة والمستثمرين وصناع السياسات ليوم كامل من الرؤى الاستراتيجية وتوقعات السوق والتواصل رفيع المستوى في قلب القاهرة.","bodyEn":"Join industry leaders, investors, and policymakers for a full day of strategic insights, market forecasts, and high-level networking in the heart of Cairo.","status":"published","metadata":{"startDate":"2025-12-15T08:00:00.000Z","endDate":"2025-12-15T18:00:00.000Z","startTime":"08:00 AM","endTime":"06:00 PM","location":"The St. Regis Cairo","category":"conference","categoryLabel":"Conference","eventType":"In-Person","image":"/images/events/summit.jpg","isPaid":true}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 11:36:39.278');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue1twjy002ji8vci5tgw8v2', 'cmudx7lm6000angvcwpmxvz9h', 1, '{"type":"event","titleAr":"التنقل في ضريبة الشركات في الإمارات: دليل للشركات المصرية","titleEn":"Navigating UAE Corporate Tax: A Guide for Egyptian Businesses","bodyAr":"مشورة استراتيجية للشركات المصرية التي تتوسع في دولة الإمارات العربية المتحدة والتنقل في نظام ضريبة الشركات الجديد.","bodyEn":"Strategic advice for Egyptian companies expanding to the UAE and navigating the new corporate tax regime.","status":"published","metadata":{"startDate":"2026-01-22T15:00:00.000Z","endDate":"2026-01-22T17:00:00.000Z","startTime":"03:00 PM","endTime":"05:00 PM","location":"Online via Zoom","category":"seminar","categoryLabel":"Legal Seminar","eventType":"Virtual","image":"/images/events/uae-tax.jpg","isPaid":false}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 11:58:01.486');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue29q9i002mi8vc4z1norsl', 'cmudx7llh0009ngvc2unwhic7', 1, '{"type":"event","titleAr":"تحديثات المعايير الدولية لإعداد التقارير المالية (IFRS) وأفضل الممارسات","titleEn":"IFRS Updates and Financial Reporting Best Practices","bodyAr":"تعمق في أحدث معايير التقارير المالية الدولية وتأثيرها على إعداد التقارير المحلية.","bodyEn":"Deep dive into the latest International Financial Reporting Standards and their impact on local reporting.","status":"published","metadata":{"startDate":"2026-01-10T10:00:00.000Z","endDate":"2026-01-10T14:00:00.000Z","startTime":"10:00 AM","endTime":"02:00 PM","location":"Sherif Yousry Advisory HQ","category":"workshop","categoryLabel":"Tax Workshop","eventType":"In-Person","image":"/images/events/ifrs.jpg","isPaid":true}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 12:10:19.830');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue2a2oq002ni8vc1rwt6w4s', 'cmudx7ljg0006ngvc5w2q0voc', 1, '{"type":"event","titleAr":"الإطار القانوني للمستثمرين الأجانب في منطقة الشرق الأوسط وشمال أفريقيا","titleEn":"Legal Framework for Foreign Investors in the MENA Region","bodyAr":"فهم المشهد التنظيمي، وحماية الاستثمارات، والهيكلة القانونية للكيانات الأجنبية التي تعمل في منطقة الشرق الأوسط وشمال أفريقيا.","bodyEn":"Understanding the regulatory landscape, investment protections, and legal structuring for foreign entities operating in the MENA region.","status":"published","metadata":{"startDate":"2025-11-12T14:00:00.000Z","endDate":"2025-11-12T16:30:00.000Z","startTime":"02:00 PM","endTime":"04:30 PM","location":"Online via Zoom","category":"seminar","categoryLabel":"Legal Seminar","eventType":"Virtual","image":"/images/events/legal-seminar.jpg","isPaid":false}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 12:10:35.930');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue3qrkz002ui8vczv6pon0a', 'cmue38en8000708vcxwy31ai2', 1, '{"type":"service","titleAr":"الضرائب المباشرة وغير المباشرة","titleEn":"Direct & Indirect Taxation","bodyAr":"ضريبة دخل الشركات، ضريبة القيمة المضافة، ضريبة الاستقطاع وضريبة الدمغة، مُقدَّمة بدقة وفي الوقت المحدد.","bodyEn":"Corporate income tax, VAT, withholding and stamp tax, filed accurately and on time.","status":"published","metadata":{"serviceType":"sub-service","categorySlug":"tax-advisory","displayOrder":1,"shortDescriptionEn":"Corporate income tax, VAT, withholding and stamp tax, filed accurately and on time.","shortDescriptionAr":"ضريبة دخل الشركات، ضريبة القيمة المضافة، ضريبة الاستقطاع وضريبة الدمغة، مُقدَّمة بدقة وفي الوقت المحدد.","fullDescriptionEn":"Corporate income tax, VAT, withholding and stamp tax compliance and advisory. We prepare and file your tax returns accurately and on time, keep your books reconciled with tax positions, and advise on the tax consequences of transactions before they happen.","fullDescriptionAr":"الامتثال والاستشارات في ضريبة دخل الشركات وضريبة القيمة المضافة وضريبة الاستقطاع وضريبة الدمغة. نُعِدّ إقراراتك الضريبية ونُقدِّمها بدقة وفي الوقت المحدد، ونحافظ على توافق دفاترك مع المواقف الضريبية، ونُقدِّم المشورة بشأن التبعات الضريبية للمعاملات قبل وقوعها."}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 12:51:34.307');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue8g0ve0039i8vch52x7m6c', 'cmue38en8000708vcxwy31ai2', 2, '{"type":"service","titleAr":"الضرائب المباشرة وغير المباشرة","titleEn":"Direct & Indirect Taxation","bodyAr":"ضريبة دخل الشركات، ضريبة القيمة المضافة، ضريبة الاستقطاع وضريبة الدمغة، مُقدَّمة بدقة وفي الوقت المحدد.","bodyEn":"Corporate income tax, VAT, withholding and stamp tax, filed accurately and on time.","status":"published","metadata":{"serviceType":"sub-service","categorySlug":"tax-advisory","displayOrder":1,"icon":null,"shortDescriptionEn":"Corporate income tax, VAT, withholding and stamp tax, filed accurately and on time.","shortDescriptionAr":"ضريبة دخل الشركات، ضريبة القيمة المضافة، ضريبة الاستقطاع وضريبة الدمغة، مُقدَّمة بدقة وفي الوقت المحدد.","fullDescriptionEn":"Corporate income tax, VAT, withholding and stamp tax compliance and advisory. We prepare and file your tax returns accurately and on time, keep your books reconciled with tax positions, and advise on the tax consequences of transactions before they happen.","fullDescriptionAr":"الامتثال والاستشارات في ضريبة دخل الشركات وضريبة القيمة المضافة وضريبة الاستقطاع وضريبة الدمغة. نُعِدّ إقراراتك الضريبية ونُقدِّمها بدقة وفي الوقت المحدد، ونحافظ على توافق دفاترك مع المواقف الضريبية، ونُقدِّم المشورة بشأن التبعات الضريبية للمعاملات قبل وقوعها.","image":null,"imageId":null}}', '["metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 15:03:11.210');
INSERT IGNORE INTO `ContentRevision` (`id`, `contentId`, `revisionNumber`, `previousState`, `changedFields`, `changedById`, `createdAt`) VALUES ('cmue8wk18003li8vceugdk7gn', 'cmue38en8000708vcxwy31ai2', 3, '{"type":"service","titleAr":"الضرائب المباشرة وغير المباشرة","titleEn":"Direct & Indirect Taxation","bodyAr":"ضريبة دخل الشركات، ضريبة القيمة المضافة، ضريبة الاستقطاع وضريبة الدمغة، مُقدَّمة بدقة وفي الوقت المحدد.","bodyEn":"<p class=\\"service-lead\\">Accurate returns, filed on time, with every position documented before the Egyptian Tax Authority asks for it.</p>\\n\\n<h2 class=\\"service-h2\\">Compliance is now digital, and so is scrutiny</h2>\\n<p class=\\"service-p\\">Under the Unified Tax Procedures Law No. 206 of 2020, returns, invoices and payments flow through the Egyptian Tax Authority\'s electronic systems. The Authority can now match your filings against the data submitted by your customers and suppliers.</p>\\n<p class=\\"service-p\\">Small inconsistencies between the VAT return, the e-invoices and the corporate tax return have become a common trigger for inspection. For foreign-owned companies the stakes are higher: tax cost feeds directly into the results reported to the parent and the cash available for dividends.</p>\\n\\n<h2 class=\\"service-h2\\">How we help</h2>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Corporate income tax:</strong> Preparation and filing of the annual return under Income Tax Law No. 91 of 2005, computation of taxable profit, review of deductible expenses and provisions, and planning for the use of carried-forward losses.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Value added tax:</strong> Registration, monthly returns under VAT Law No. 67 of 2016, input tax recovery, treatment of exempt, zero-rated and export supplies, and table tax on scheduled goods and services.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Withholding tax:</strong> Quarterly filings under the advance payment system and withholding on payments to non-residents, with reconciliations that support the credits you claim.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Stamp tax:</strong> Assessment of stamp tax on contracts, advertising, banking facilities and other taxable instruments under Stamp Tax Law No. 111 of 1980.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Tax health check:</strong> A review of the open tax years that identifies exposures and corrects them before the Authority\'s inspection does.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Tax calendar:</strong> One schedule of every filing and payment deadline, owned by us and shared with your finance team, so nothing depends on memory.</p>\\n\\n<h2 class=\\"service-h2\\">Our approach</h2>\\n<ol class=\\"service-steps\\">\\n  <li class=\\"service-step\\">\\n    <span class=\\"service-step-num\\">Step 1</span>\\n    <span class=\\"service-step-title\\">Diagnose</span>\\n    <span class=\\"service-step-body\\">Review returns, accounting records and e-invoice data for the open years.</span>\\n  </li>\\n  <li class=\\"service-step\\">\\n    <span class=\\"service-step-num\\">Step 2</span>\\n    <span class=\\"service-step-title\\">Correct</span>\\n    <span class=\\"service-step-body\\">Close gaps and document the positions taken.</span>\\n  </li>\\n  <li class=\\"service-step\\">\\n    <span class=\\"service-step-num\\">Step 3</span>\\n    <span class=\\"service-step-title\\">File</span>\\n    <span class=\\"service-step-body\\">Prepare and submit returns within the statutory deadlines.</span>\\n  </li>\\n  <li class=\\"service-step\\">\\n    <span class=\\"service-step-num\\">Step 4</span>\\n    <span class=\\"service-step-title\\">Monitor</span>\\n    <span class=\\"service-step-body\\">Track changes in law and ETA practice, and explain what each one means for you.</span>\\n  </li>\\n</ol>\\n\\n<div class=\\"service-highlight\\">\\n  <span class=\\"service-highlight-title\\">Who we advise</span>\\n  <span class=\\"service-highlight-body\\">Egyptian subsidiaries of foreign groups, family-owned and investor-backed companies, and foreign investors in their first years of operation in Egypt.</span>\\n</div>\\n\\n<h2 class=\\"service-h2\\">Why choose Sherif Yousry?</h2>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Licensed accountants and advisers:</strong> Our team brings together licensed accountants, registered statutory auditors and certified tax experts, with more than two decades of professional experience across the Egyptian market.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">International standards:</strong> We work to International Financial Reporting Standards and International Standards on Auditing alongside Egyptian standards, so our work carries the same weight with a foreign parent, a lender or an investor as it does with the Egyptian Tax Authority.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">International tax expertise:</strong> We bring hands-on experience in double tax treaties, transfer pricing and cross-border structuring, aligned with OECD standards, to investors entering Egypt and to groups operating across borders.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Partner-led, team-delivered:</strong> Every engagement is led by a partner and supported by a dedicated team from the initial consultation to the final deliverable, with no handoffs between departments. Clients benefit from senior-level judgement, continuity and accountability at every stage.</p>\\n<p class=\\"service-p\\"><strong class=\\"service-strong\\">Digital by design:</strong> Our services are delivered through a digital-first model. Clients can securely share documents through our client portal, track engagement progress, and connect with our team through virtual meetings, making it possible to work with us seamlessly from anywhere in the world.</p>\\n\\n<h2 class=\\"service-h2\\">Questions investors ask</h2>\\n<div class=\\"service-faq-list\\">\\n  <details class=\\"service-faq\\" open>\\n    <summary class=\\"service-faq-q\\">What is the corporate income tax rate in Egypt?</summary>\\n    <p class=\\"service-faq-a\\">The standard rate is 22.5% of taxable profit. Different rates apply to certain entities, such as companies in oil exploration and production, and smaller businesses may qualify for the simplified tax regime.</p>\\n  </details>\\n  <details class=\\"service-faq\\">\\n    <summary class=\\"service-faq-q\\">When is the annual corporate tax return due?</summary>\\n    <p class=\\"service-faq-a\\">Within four months of the financial year end. For a company with a 31 December year end, that means by 30 April.</p>\\n  </details>\\n  <details class=\\"service-faq\\">\\n    <summary class=\\"service-faq-q\\">Are foreign-owned companies taxed differently from Egyptian companies?</summary>\\n    <p class=\\"service-faq-a\\">No. A company incorporated in Egypt is taxed on the same basis whoever owns it. What changes the tax position is the investment regime it operates under, such as a free zone or an economic zone.</p>\\n  </details>\\n</div>\\n\\n<p class=\\"service-closing\\">Talk to us about your corporate tax and VAT position.</p>","status":"published","metadata":{"serviceType":"sub-service","categorySlug":"tax-advisory","displayOrder":1,"icon":null,"shortDescriptionEn":"Corporate income tax, VAT, withholding and stamp tax, filed accurately and on time.","shortDescriptionAr":"ضريبة دخل الشركات، ضريبة القيمة المضافة، ضريبة الاستقطاع وضريبة الدمغة، مُقدَّمة بدقة وفي الوقت المحدد.","fullDescriptionEn":"Corporate income tax, VAT, withholding and stamp tax compliance and advisory. We prepare and file your tax returns accurately and on time, keep your books reconciled with tax positions, and advise on the tax consequences of transactions before they happen.","fullDescriptionAr":"الامتثال والاستشارات في ضريبة دخل الشركات وضريبة القيمة المضافة وضريبة الاستقطاع وضريبة الدمغة. نُعِدّ إقراراتك الضريبية ونُقدِّمها بدقة وفي الوقت المحدد، ونحافظ على توافق دفاترك مع المواقف الضريبية، ونُقدِّم المشورة بشأن التبعات الضريبية للمعاملات قبل وقوعها.","image":"/uploads/1788525161878-y6wtv0hy.jpeg","imageId":"cmtmxpb4v00027kvcqyav6yee"}}', '["bodyEn","metadata"]', 'cadmini0o95r2vx5mux5f59q', '2026-09-23 15:16:02.540');
